 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def stripe_indices(lines):
        found = []
        for i, line in enumerate(lines):
            counts = {}
            for x in line:
                if x != 0:
                    counts[x] = counts.get(x, 0) + 1
            if counts:
                color, count = max(counts.items(), key=lambda kv: kv[1])
                # The colored bars remain dominant despite intersections with
                # the perpendicular bars.
                if count >= (len(line) + 1) // 2:
                    found.append(i)
        return found

    rows = stripe_indices(grid)
    cols = stripe_indices([[grid[r][c] for r in range(h)] for c in range(w)])
    out = [[0 for _ in range(2 * len(cols) + 1)] for _ in range(2 * len(rows) + 1)]

    row_colors = []
    for r in rows:
        counts = {}
        for c in range(w):
            if grid[r][c] != 0:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
        row_colors.append(max(counts, key=counts.get))
    col_colors = []
    for c in cols:
        counts = {}
        for r in range(h):
            if grid[r][c] != 0:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
        col_colors.append(max(counts, key=counts.get))

    for i, color in enumerate(row_colors):
        out[2 * i + 1] = [color] * len(out[0])
    for j, color in enumerate(col_colors):
        for r in range(len(out)):
            out[r][2 * j + 1] = col_colors[j]
    # At a bar crossing, preserve the observed input crossing color.
    for i, r in enumerate(rows):
        for j, c in enumerate(cols):
            out[2 * i + 1][2 * j + 1] = grid[r][c]
    return out
